/// VS Code file-icon theme manifest (vscode-symbols); `iconPath`s are
/// `./icons/{files,folders}/<name>.svg`, i.e. `fileIcon` paths under `./icons/`.
pub const file_icons_manifest = @embedFile("assets/file-icons/file-icons.json");
pub const file_icons_license = @embedFile("assets/file-icons/LICENSE.symbols");

/// Embedded file-icon bytes by relative path (`files/rust.svg`, `folders/folder-src.svg`;
/// one upstream icon, `files/nuxt.png`, is a PNG).
pub fn fileIcon(rel_path: []const u8) ?[]const u8 {
    const i = std.sort.binarySearch([]const u8, &file_icon_paths, rel_path, struct {
        fn order(key: []const u8, item: []const u8) std.math.Order {
            return std.mem.order(u8, key, item);
        }
    }.order) orelse return null;
    return file_icon_svgs[i];
}

