test {
    for (std.enums.values(Icon)) |icon| {
        try std.testing.expect(std.mem.indexOf(u8, icon.svg(), "<svg") != null);
        try std.testing.expect(std.mem.indexOf(u8, icon.svg(), "viewBox") != null);
        try std.testing.expectEqual(icon, Icon.fromPath(icon.path()).?);
    }
    try std.testing.expectEqualStrings("pen-new-square", Icon.pen_new_square.fileName());
    try std.testing.expect(Icon.fromPath("icons/nope.svg") == null);
    for (std.enums.values(Font)) |f| {
        const d = f.info().data;
        try std.testing.expect(d.len > 1024 and std.mem.readInt(u32, d[0..4], .big) == 0x00010000);
    }
    for (file_icon_paths) |p| {
        if (std.mem.endsWith(u8, p, ".svg")) try std.testing.expect(std.mem.indexOf(u8, fileIcon(p).?, "<svg") != null);
    }
    try std.testing.expect(fileIcon("files/does-not-exist.svg") == null);
    try std.testing.expect(std.mem.indexOf(u8, file_icons_manifest, "iconDefinitions") != null);
}
